typedef struct { const uint8_t *p,*end; } R;
static void need(R*r,size_t n){if((size_t)(r->end-r->p)<n){fputs("truncated capsule\n",stderr);exit(3);}}
static const uint8_t*take(R*r,size_t n){need(r,n);const uint8_t*p=r->p;r->p+=n;return p;}
static uint8_t u8(R*r){return *take(r,1);} static uint16_t u16(R*r){const uint8_t*p=take(r,2);return p[0]|((uint16_t)p[1]<<8);} static uint32_t u32(R*r){const uint8_t*p=take(r,4);return p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);} static uint64_t u64(R*r){uint64_t a=u32(r),b=u32(r);return a|(b<<32);}
static uint8_t*slurp(const char*path,size_t*n){FILE*f=fopen(path,"rb");if(!f){perror(path);exit(2);}fseek(f,0,SEEK_END);long z=ftell(f);rewind(f);uint8_t*p=malloc((size_t)z);if(!p||fread(p,1,(size_t)z,f)!=(size_t)z){fprintf(stderr,"read %s\n",path);exit(2);}fclose(f);*n=(size_t)z;return p;}
typedef struct{uint8_t*p;uint32_t n;}Dom;
static uint32_t rd32(const Dom*d,uint32_t a){uint32_t o=a&0x1fffff;return o+4<=d->n?(uint32_t)d->p[o]|((uint32_t)d->p[o+1]<<8)|((uint32_t)d->p[o+2]<<16)|((uint32_t)d->p[o+3]<<24):0;}static int32_t rs32(const Dom*d,uint32_t a){return(int32_t)rd32(d,a);}static uint16_t rd16(const Dom*d,uint32_t a){uint32_t o=a&0x1fffff;return o+2<=d->n?d->p[o]|((uint16_t)d->p[o+1]<<8):0;}
static int green(int t){return t==1||t==4||t==9||t==10;}
typedef struct{int used,live,slot,type;uint32_t spawn,last,mature,state1,despawn;int32_t x,y,z;uint16_t first_extra,last_extra;int32_t max_rise,min_hdist;uint32_t max_rise_frame;uint64_t near_frames,ground_frames,passive_blocks;uint32_t modes;}Track;
typedef struct{uint32_t movie;int32_t x,y,z,vx,vy,vz,floor;uint16_t mode,ground,action,flags,interact;}Player;
static Player player(const Dom*d,uint32_t m){Player p={m,rs32(d,0x800a6500),rs32(d,0x800a6504),rs32(d,0x800a6508),rs32(d,0x800a652c),rs32(d,0x800a6530),rs32(d,0x800a6534),rs32(d,0x800a6548),rd16(d,0x800a6580),rd16(d,0x800a6582),rd16(d,0x800a6588),rd16(d,0x800a6590),rd16(d,0x800a659e)};return p;}
static int nearest(Track*t,int nt,const Player*p,int *hd){int best=-1;int64_t bd=INT64_MAX;for(int i=0;i<nt;i++)if(t[i].live){int64_t dx=(int64_t)p->x-t[i].x,dz=(int64_t)p->z-t[i].z,q=dx*dx+dz*dz;if(q<bd){bd=q;best=i;}}if(best>=0){int64_t lo=0,hi=1000000;while(lo+1<hi){int64_t m=(lo+hi)/2;if(m*m<=bd)lo=m;else hi=m;}*hd=(int)lo;}return best;}
int main(int ac,char**av){if(ac!=2){fprintf(stderr,"usage: %s capsule_dir\n",av[0]);return 2;}char pat[PATH_MAX];snprintf(pat,sizeof pat,"%s/chunks/*.tcap.zst",av[1]);glob_t g={0};if(glob(pat,0,NULL,&g)){fputs("no chunks\n",stderr);return 2;}Dom d[4]={{0}};char**names=NULL;uint32_t nn=0,mode0=0;Track tr[64]={{0}};int nt=0;int slot_track[20];for(int i=0;i<20;i++)slot_track[i]=-1;uint64_t frames=0,passive=0,walker=0,sector=0,landing=0,ycommit=0,special=0;uint32_t first_movie=0,last_movie=0;Player prev={0};int have_prev=0,seg_track=-1;uint32_t seg_start=0;int32_t seg_y=0;unsigned seg_count=0,hashes=0;printf("EVENTS\n");
for(size_t fi=0;fi<g.gl_pathc;fi++){size_t cn;uint8_t*c=slurp(g.gl_pathv[fi],&cn);unsigned long long zn=ZSTD_getFrameContentSize(c,cn);if(zn==ZSTD_CONTENTSIZE_ERROR||zn==ZSTD_CONTENTSIZE_UNKNOWN){fputs("bad zstd\n",stderr);return 3;}uint8_t*raw=malloc((size_t)zn);size_t got=ZSTD_decompress(raw,(size_t)zn,c,cn);free(c);if(ZSTD_isError(got)||got!=zn){fputs("decompress error\n",stderr);return 3;}R r={raw,raw+got};if(memcmp(take(&r,8),"DSTCAP01",8)||u32(&r)!=1){fputs("schema error\n",stderr);return 3;}uint32_t bm=u32(&r);(void)u64(&r);uint32_t n=u32(&r);if(!names){mode0=bm;nn=n;names=calloc(n,sizeof(*names));for(uint32_t i=0;i<n;i++){uint16_t z=u16(&r);names[i]=calloc(z+1,1);memcpy(names[i],take(&r,z),z);}}else{if(bm!=mode0||n!=nn){fputs("schema drift\n",stderr);return 3;}for(uint32_t i=0;i<n;i++){uint16_t z=u16(&r);if(strlen(names[i])!=z||memcmp(names[i],take(&r,z),z)){fputs("register drift\n",stderr);return 3;}}}
while(r.p<r.end){if(u8(&r)!=1){fputs("tag error\n",stderr);return 3;}uint64_t frame=u64(&r),cycle=u64(&r);uint32_t movie=u32(&r),pc=u32(&r);uint32_t initial=u32(&r);(void)frame;(void)cycle;(void)pc;(void)initial;for(uint32_t i=0;i<nn;i++)u32(&r);for(int q=0;q<3;q++){uint32_t id=u32(&r),sz=u32(&r),runs=u32(&r);const uint8_t*want=take(&r,32);if(id<1||id>3)return 3;if(!d[id].p){d[id].p=calloc(1,sz);d[id].n=sz;}if(d[id].n!=sz)return 3;for(uint32_t j=0;j<runs;j++){uint32_t off=u32(&r),len=u32(&r);if((uint64_t)off+len>sz)return 3;memcpy(d[id].p+off,take(&r,len),len);}uint8_t h[32];SHA256(d[id].p,sz,h);if(memcmp(h,want,32)){fprintf(stderr,"domain hash mismatch movie=%u id=%u\n",movie,id);return 4;}hashes++;}
uint64_t bc=u64(&r),pb=0;for(uint64_t j=0;j<bc;j++){uint32_t a=u32(&r);uint64_t count=u64(&r);if(a==0x8005cce8)pb+=count;if(a>=0x8005bfbc&&a<0x8005c110)walker+=count;if(a>=0x80038e48&&a<0x80038eac)sector+=count;if(a>=0x80035e00&&a<0x80036040)landing+=count;if(a>=0x80036c80&&a<0x80036e70)ycommit+=count;if(a>=0x8005c110&&a<0x8005cce8)special+=count;}passive+=pb;
Player p=player(&d[1],movie);if(frames==0)first_movie=movie;last_movie=movie;
for(int s=0;s<20;s++){uint32_t a=0x80090bf0u+(uint32_t)s*0x30u;int type=(int16_t)rd16(&d[1],a);int old=slot_track[s];if(old>=0&&(!green(type)||type!=tr[old].type)){tr[old].live=0;tr[old].despawn=movie;printf("despawn movie=%u slot=%d type=%d lifetime=%u\n",movie,s,tr[old].type,movie-tr[old].spawn);slot_track[s]=-1;old=-1;}if(green(type)&&old<0){if(nt>=64)return 5;int k=nt++;tr[k].used=tr[k].live=1;tr[k].slot=s;tr[k].type=type;tr[k].spawn=movie;tr[k].last=movie;tr[k].mature=UINT32_MAX;tr[k].state1=UINT32_MAX;tr[k].x=rs32(&d[1],a+8);tr[k].y=rs32(&d[1],a+12);tr[k].z=rs32(&d[1],a+16);tr[k].first_extra=tr[k].last_extra=rd16(&d[1],a+46);tr[k].min_hdist=INT_MAX;slot_track[s]=k;old=k;printf("spawn movie=%u slot=%d type=%d pos=(%d,%d,%d) state=%d extra=0x%04x\n",movie,s,type,tr[k].x,tr[k].y,tr[k].z,(int16_t)rd16(&d[1],a+2),tr[k].first_extra);}if(old>=0){Track*t=&tr[old];t->last=movie;uint16_t ex=rd16(&d[1],a+46);int st=(int16_t)rd16(&d[1],a+2);if(t->mature==UINT32_MAX&&(ex&4)){t->mature=movie;printf("mature movie=%u slot=%d type=%d extra=0x%04x\n",movie,s,type,ex);}if(t->state1==UINT32_MAX&&st==1)t->state1=movie;if(ex!=t->last_extra){printf("extra movie=%u slot=%d type=%d 0x%04x->0x%04x\n",movie,s,type,t->last_extra,ex);t->last_extra=ex;}t->passive_blocks+=pb;}}
int hd=0,k=nearest(tr,nt,&p,&hd);if(k>=0&&hd<50000){Track*t=&tr[k];t->near_frames++;if(hd<t->min_hdist)t->min_hdist=hd;int32_t rise=t->y-p.y;if(rise>t->max_rise){t->max_rise=rise;t->max_rise_frame=movie;}if(p.ground)t->ground_frames++;if(p.mode<32)t->modes|=1u<<p.mode;}
int stable=(k>=0&&hd<20000&&p.ground&&p.vy==0&&have_prev&&p.y==prev.y);if(stable){if(seg_track!=k||seg_y!=p.y){if(seg_track>=0&&seg_count>=4)printf("ground_hold frames=%u..%u dur=%u slot=%d type=%d y=%d plant_delta=%d\n",seg_start,movie-1,seg_count,tr[seg_track].slot,tr[seg_track].type,seg_y,tr[seg_track].y-seg_y);seg_track=k;seg_start=movie-1;seg_y=p.y;seg_count=2;}else seg_count++;}else{if(seg_track>=0&&seg_count>=4)printf("ground_hold frames=%u..%u dur=%u slot=%d type=%d y=%d plant_delta=%d\n",seg_start,movie-1,seg_count,tr[seg_track].slot,tr[seg_track].type,seg_y,tr[seg_track].y-seg_y);seg_track=-1;seg_count=0;}
if(k>=0&&hd<30000&&have_prev&&prev.vy<0&&p.vy>=0)printf("near_apex movie=%u slot=%d type=%d y=%d rise=%d mode=%u ground=%u vy=%d\n",movie,tr[k].slot,tr[k].type,p.y,tr[k].y-p.y,p.mode,p.ground,p.vy);
prev=p;have_prev=1;frames++;}
free(raw);}
if(seg_track>=0&&seg_count>=4)printf("ground_hold frames=%u..%u dur=%u slot=%d type=%d y=%d plant_delta=%d\n",seg_start,last_movie,seg_count,tr[seg_track].slot,tr[seg_track].type,seg_y,tr[seg_track].y-seg_y);
for(int s=0;s<20;s++)if(slot_track[s]>=0){tr[slot_track[s]].live=0;tr[slot_track[s]].despawn=UINT32_MAX;}
printf("TRACKS\n");for(int i=0;i<nt;i++)printf("track=%d slot=%d type=%d spawn=%u mature=%s%u state1=%s%u despawn=%s%u observed=%u pos=(%d,%d,%d) extra=0x%04x->0x%04x nearest=%d max_rise=%d@%u near_frames=%"PRIu64" ground_frames=%"PRIu64" modes=0x%08x passive_blocks=%"PRIu64"\n",i,tr[i].slot,tr[i].type,tr[i].spawn,tr[i].mature==UINT32_MAX?"open:":"",tr[i].mature,tr[i].state1==UINT32_MAX?"open:":"",tr[i].state1,tr[i].despawn==UINT32_MAX?"open:":"",tr[i].despawn,tr[i].last-tr[i].spawn+1,tr[i].x,tr[i].y,tr[i].z,tr[i].first_extra,tr[i].last_extra,tr[i].min_hdist,tr[i].max_rise,tr[i].max_rise_frame,tr[i].near_frames,tr[i].ground_frames,tr[i].modes,tr[i].passive_blocks);
printf("SUMMARY chunks=%zu frames=%"PRIu64" movie=%u..%u domain_hashes=%u all_hashes_ok=true passive_blocks=%"PRIu64" walker_blocks=%"PRIu64" sector_lookup_blocks=%"PRIu64" landing_blocks=%"PRIu64" ycommit_blocks=%"PRIu64" special_plant_blocks=%"PRIu64" tracks=%d\n",g.gl_pathc,frames,first_movie,last_movie,hashes,passive,walker,sector,landing,ycommit,special,nt);globfree(&g);return 0;}
